-- Auth Service initial schema.
-- IDs are UUID v4 generated by the application; timestamps are TIMESTAMPTZ in UTC.

CREATE SCHEMA IF NOT EXISTS auth;

CREATE TYPE auth.account_status AS ENUM (
    'PENDING_VERIFICATION',
    'ACTIVE',
    'LOCKED',
    'DELETED'
);

CREATE TYPE auth.role_code AS ENUM (
    'USER',
    'ADMIN'
);

CREATE TYPE auth.deletion_reason AS ENUM (
    'GDPR_REQUEST',
    'ADMIN_DELETION'
);

CREATE TYPE auth.jwt_key_status AS ENUM (
    'ACTIVE',
    'PHASE_OUT',
    'RETIRED'
);

CREATE OR REPLACE FUNCTION auth.set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;

CREATE TABLE auth.accounts (
    id UUID PRIMARY KEY,

    email VARCHAR(254),
    email_normalized VARCHAR(254),
    password_hash TEXT,

    status auth.account_status NOT NULL DEFAULT 'PENDING_VERIFICATION',

    failed_login_count INTEGER NOT NULL DEFAULT 0,
    last_failed_login_at TIMESTAMPTZ,
    locked_until TIMESTAMPTZ,
    password_changed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    deleted_at TIMESTAMPTZ,
    hard_delete_after TIMESTAMPTZ,
    deletion_reason auth.deletion_reason,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT uq_accounts_email_normalized UNIQUE (email_normalized),

    CONSTRAINT chk_accounts_failed_login_count
        CHECK (failed_login_count >= 0),

    CONSTRAINT chk_accounts_email_format
        CHECK (
            email IS NULL
            OR (char_length(email) <= 254 AND position('@' IN email) > 1)
        ),

    CONSTRAINT chk_accounts_email_normalized
        CHECK (
            email IS NULL
            OR email_normalized = lower(btrim(email))
        ),

    CONSTRAINT chk_accounts_lock_state
        CHECK (
            (status = 'LOCKED' AND locked_until IS NOT NULL)
            OR (status <> 'LOCKED' AND locked_until IS NULL)
        ),

    CONSTRAINT chk_accounts_deleted_state
        CHECK (
            (
                status = 'DELETED'
                AND email IS NULL
                AND email_normalized IS NULL
                AND password_hash IS NULL
                AND deleted_at IS NOT NULL
                AND hard_delete_after = deleted_at + INTERVAL '90 days'
                AND deletion_reason IS NOT NULL
            )
            OR
            (
                status <> 'DELETED'
                AND email IS NOT NULL
                AND email_normalized IS NOT NULL
                AND password_hash IS NOT NULL
                AND deleted_at IS NULL
                AND hard_delete_after IS NULL
                AND deletion_reason IS NULL
            )
        )
);

CREATE TRIGGER trg_accounts_set_updated_at
BEFORE UPDATE ON auth.accounts
FOR EACH ROW
EXECUTE FUNCTION auth.set_updated_at();

CREATE TABLE auth.account_roles (
    account_id UUID NOT NULL
        REFERENCES auth.accounts(id) ON DELETE CASCADE,

    role_code auth.role_code NOT NULL,

    PRIMARY KEY (account_id, role_code)
);

CREATE TABLE auth.refresh_tokens (
    id UUID PRIMARY KEY,

    account_id UUID NOT NULL
        REFERENCES auth.accounts(id) ON DELETE CASCADE,

    family_id UUID NOT NULL,

    -- SHA-256 of the opaque refresh token; exactly 32 bytes.
    token_hash BYTEA NOT NULL,

    device_id UUID,
    device_name VARCHAR(200),
    user_agent TEXT,
    ip_address INET,

    expires_at TIMESTAMPTZ NOT NULL,
    absolute_expires_at TIMESTAMPTZ NOT NULL,

    revoked_at TIMESTAMPTZ,
    replaced_by UUID
        REFERENCES auth.refresh_tokens(id) ON DELETE SET NULL,

    last_used_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT uq_refresh_tokens_token_hash UNIQUE (token_hash),

    CONSTRAINT chk_refresh_tokens_hash_length
        CHECK (octet_length(token_hash) = 32),

    CONSTRAINT chk_refresh_tokens_expiry
        CHECK (expires_at <= absolute_expires_at),

    CONSTRAINT chk_refresh_tokens_replacement
        CHECK (replaced_by IS NULL OR revoked_at IS NOT NULL)
);

CREATE INDEX idx_refresh_tokens_account_active
    ON auth.refresh_tokens (account_id, expires_at DESC)
    WHERE revoked_at IS NULL;

CREATE INDEX idx_refresh_tokens_family_active
    ON auth.refresh_tokens (family_id, expires_at DESC)
    WHERE revoked_at IS NULL;

CREATE INDEX idx_refresh_tokens_cleanup
    ON auth.refresh_tokens (expires_at, revoked_at);

CREATE TABLE auth.jwt_keys (
    kid UUID PRIMARY KEY,

    algorithm VARCHAR(16) NOT NULL DEFAULT 'RS256',
    public_key_pem TEXT NOT NULL,

    -- AES-256-GCM ciphertext. The master key is supplied by Auth Service secret.
    private_key_ciphertext BYTEA NOT NULL,
    private_key_nonce BYTEA NOT NULL,
    encryption_key_version SMALLINT NOT NULL DEFAULT 1,

    status auth.jwt_key_status NOT NULL,

    activated_at TIMESTAMPTZ,
    phase_out_at TIMESTAMPTZ,
    retired_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT chk_jwt_keys_algorithm
        CHECK (algorithm = 'RS256'),

    CONSTRAINT chk_jwt_keys_nonce_length
        CHECK (octet_length(private_key_nonce) = 12),

    CONSTRAINT chk_jwt_keys_encryption_key_version
        CHECK (encryption_key_version > 0)
);

CREATE UNIQUE INDEX uq_jwt_keys_one_active
    ON auth.jwt_keys ((status = 'ACTIVE'))
    WHERE status = 'ACTIVE';

CREATE INDEX idx_jwt_keys_jwks
    ON auth.jwt_keys (status, phase_out_at)
    WHERE status IN ('ACTIVE', 'PHASE_OUT');

CREATE INDEX idx_accounts_hard_delete
    ON auth.accounts (hard_delete_after)
    WHERE status = 'DELETED';
